BEGIN;
LOCK TABLE forecast_workflow,forecast_line,forecast_workflow_history IN ACCESS EXCLUSIVE MODE;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM forecast_workflow) THEN RAISE EXCEPTION 'Refusing to remove retained forecast evidence' USING ERRCODE='55000';END IF;END $$;
REVOKE ALL ON FUNCTION refs_forecast_create_hash(uuid,uuid,uuid,text,text,jsonb,text),refs_forecast_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_forecast_payload(uuid,uuid,uuid),refs_create_forecast_workflow(uuid,uuid,uuid,text,text,jsonb,text,text,text),refs_transition_forecast_workflow(uuid,uuid,uuid,text,bigint,text,text,text),refs_read_forecast_workflow(uuid,uuid,uuid) FROM refs_app;
DROP TRIGGER forecast_workflow_protect ON forecast_workflow;DROP TRIGGER forecast_line_append_only ON forecast_line;DROP TRIGGER forecast_history_append_only ON forecast_workflow_history;DROP FUNCTION refs_read_forecast_workflow(uuid,uuid,uuid);DROP FUNCTION refs_transition_forecast_workflow(uuid,uuid,uuid,text,bigint,text,text,text);DROP FUNCTION refs_create_forecast_workflow(uuid,uuid,uuid,text,text,jsonb,text,text,text);DROP FUNCTION refs_forecast_payload(uuid,uuid,uuid);DROP FUNCTION refs_forecast_transition_hash(uuid,uuid,uuid,text,bigint,text);DROP FUNCTION refs_forecast_create_hash(uuid,uuid,uuid,text,text,jsonb,text);DROP FUNCTION refs_guard_forecast_workflow();DROP TABLE forecast_workflow_gate;DROP TABLE forecast_workflow_history;DROP TABLE forecast_line;DROP TABLE forecast_workflow;UPDATE permission_catalog SET active=false,effective_to=clock_timestamp(),version=version+1 WHERE permission_code LIKE 'REPORT.FORECAST.%';DELETE FROM runtime_human_permission_authority WHERE permission_code LIKE 'REPORT.FORECAST.%';
COMMIT;
